 function quiet(t,d,heading,place,amp){const f=clamp(t/d,0,1),a=amp*Math.sin(Math.PI*f)**2*Math.sin(2*Math.PI*f),q={...S.rotations};for(const [id,sgn] of [[28,1],[31,1],[36,-1]])q[id]=norm(qm(q[id],axis(2,a*sgn)));return transform(pose(q,S.stance),heading,place);}
 function settle(f,heading,place){const k=at(KEY.sett,f,{}),base=Object.fromEntries(Object.keys(S.rotations).map(id=>[id,sl(E.rotations[id],S.rotations[id],k.v)]));return transform(pose({...base,...k.q},k.stance,[E.sourceTime,S.sourceTime,k.v]),heading,place);}
